import{_ as e,o as i,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-06-19 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-06-19 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-06-19T00:00:00.000Z","updated":"2019-06-19T00:00:00.000Z","tags":["Ceph","分布式存储","性能测试","代码布局","异常处理","API扩展","Sister API"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-06-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780459816000}'),s={name:"posts/2019/2019-06-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function o(n,t,_,p,a,S){return i(),l("div",null,[...t[0]||(t[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年6月19日 <strong>参会人员</strong>： 多位Ceph研发人员，涉及存储、字幕翻译和总结工作 <strong>会议主题</strong>： 讨论Ceph存储性能测试、代码布局、异常处理和Sister API扩展等议题</p><p><strong>会议内容</strong>：</p><p><strong>1. Ceph存储性能测试</strong></p><ul><li>研发人员汇报了性能测试的最新进展，包括相邻缓冲指针合并工作的改进和性能测试结果的更新。</li><li>讨论了与CI/CD集成的性能测试，提出了一种绕过主分支和C/Stark权限的方法，以实现更长时间的性能测试。</li></ul><p><strong>2. 代码布局</strong></p><ul><li>讨论了Ceph代码布局，包括管道和管道阶段的命名和实现方式。</li><li>提出了一种将逻辑移出PG分析器的做法，并讨论了是否需要对此进行更改。</li></ul><p><strong>3. 异常处理</strong></p><ul><li>讨论了Ceph代码中的异常处理方式，包括try-catch语句的使用。</li><li>讨论了如何处理异常和错误，以及如何确保异常能够被正确捕获和传播。</li></ul><p><strong>4. Sister API扩展</strong></p><ul><li>讨论了Sister API的扩展，包括对输入缓冲区工厂和精确读取的支持。</li><li>讨论了如何处理DPDK和POSIX网络栈之间的差异，以及如何确保数据对齐和连续性。</li></ul><p><strong>5. 其他议题</strong></p><ul><li>讨论了Ceph存储的延迟特性，以及如何优化性能。</li><li>讨论了如何处理不同类型的网络栈，以及如何为不同的用例选择最佳的网络栈。</li></ul><p><strong>决定事项</strong>：</p><ul><li>继续推进Ceph存储性能测试和代码布局的改进。</li><li>继续讨论Sister API扩展的细节，并制定相应的实现方案。</li><li>在Sister讨论列表上继续讨论Sister API扩展和输入缓冲区工厂的细节。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>研发人员将继续推进Ceph存储性能测试和代码布局的改进。</li><li>研发人员将制定Sister API扩展的实现方案，并进行相应的测试。</li><li>研发人员将继续讨论Sister API扩展和输入缓冲区工厂的细节。</li></ul><p><strong>改进点</strong>：</p><ul><li>确保了总结涵盖了会议的关键细节和讨论的主要议题。</li><li>保留了计算机科学/ceph相关领域的英文原文关键词。</li><li>修正了会议时间，原始总结中日期错误。</li></ul>',19)])])}const d=e(s,[["render",o]]);export{u as __pageData,d as default};
